-- Expands each course type's full description (shown on /courses) to
-- roughly triple its original length. brief_description (shown on the
-- homepage cards) is left untouched.

update public.course_types set
  description = 'A full-body, low-impact class focused on core strength, posture and flexibility. No equipment needed beyond a mat — great for beginners and regulars alike. Each session moves through a structured sequence of controlled, breath-led exercises that build strength from the inside out, starting with the deep stabilizing muscles most gym routines skip entirely. You''ll work through mobility, balance and coordination in the same hour, so the benefits carry over into everyday movement — better posture at your desk, less strain lifting groceries, steadier footing on stairs. Modifications are offered for every level, so newcomers and long-time regulars train side by side without anyone holding the group back.',
  description_de = 'Ein Ganzkörpertraining mit geringer Belastung, das sich auf Rumpfkraft, Haltung und Beweglichkeit konzentriert. Ausser einer Matte wird keine Ausrüstung benötigt — ideal für Einsteigerinnen und Stammgäste. Jede Stunde folgt einer strukturierten Abfolge kontrollierter, atemgeführter Übungen, die Kraft von innen nach aussen aufbauen und mit den tiefen stabilisierenden Muskeln beginnen, die die meisten Fitnessprogramme komplett auslassen. In derselben Stunde arbeitest du an Beweglichkeit, Gleichgewicht und Koordination, sodass sich die Vorteile auch im Alltag zeigen — bessere Haltung am Schreibtisch, weniger Belastung beim Einkaufstragen, sichererer Halt auf Treppen. Für jedes Niveau gibt es Anpassungen, sodass Neueinsteigerinnen und langjährige Teilnehmerinnen Seite an Seite trainieren, ohne dass jemand die Gruppe ausbremst.',
  description_fr = 'Un cours complet et à faible impact, axé sur le renforcement du centre du corps, la posture et la souplesse. Aucun équipement nécessaire à part un tapis — idéal pour les débutants comme pour les habitués. Chaque séance suit une séquence structurée d''exercices contrôlés et guidés par la respiration, qui renforcent le corps de l''intérieur en commençant par les muscles stabilisateurs profonds que la plupart des programmes de sport ignorent complètement. En une heure, vous travaillez aussi la mobilité, l''équilibre et la coordination, si bien que les bénéfices se retrouvent dans les gestes du quotidien — meilleure posture au bureau, moins de tension en portant les courses, plus de stabilité dans les escaliers. Des adaptations sont proposées à chaque niveau, afin que débutants et habitués s''entraînent côte à côte sans que personne ne freine le groupe.'
where slug = 'mat-pilates';

update public.course_types set
  description = 'Small-group sessions on the reformer machine, building controlled strength through spring-based resistance. Booking ahead is required — spots are limited. The machine''s sliding carriage and adjustable springs let you load and unload muscles far more precisely than mat work alone, so every exercise can be scaled exactly to where your body is that day. Classes stay small on purpose — usually no more than four people — so the instructor can watch your form closely and adjust resistance in real time rather than running a one-size-fits-all program. Expect a genuine full-body challenge: legs, core and upper body all get worked, often in the same fluid movement.',
  description_de = 'Kleine Gruppen trainieren am Reformer-Gerät und bauen durch federbasierten Widerstand kontrollierte Kraft auf. Eine Voranmeldung ist erforderlich — die Plätze sind begrenzt. Der Gleitwagen und die verstellbaren Federn des Geräts ermöglichen eine viel präzisere Be- und Entlastung der Muskeln als reines Mattentraining, sodass jede Übung genau auf deinen aktuellen Zustand abgestimmt werden kann. Die Kurse bleiben bewusst klein — meist nicht mehr als vier Personen —, damit die Instruktorin deine Haltung genau beobachten und den Widerstand in Echtzeit anpassen kann, statt ein Programm für alle gleich durchzuziehen. Erwarte eine echte Ganzkörper-Herausforderung: Beine, Rumpf und Oberkörper werden oft in derselben fliessenden Bewegung beansprucht.',
  description_fr = 'Des séances en petit groupe sur le reformer, pour développer une force contrôlée grâce à une résistance à ressorts. Réservation obligatoire à l''avance — places limitées. Le chariot coulissant et les ressorts réglables de la machine permettent de charger et décharger les muscles avec bien plus de précision que le seul travail au tapis, si bien que chaque exercice peut être ajusté exactement à l''état de votre corps ce jour-là. Les cours restent volontairement petits — généralement pas plus de quatre personnes — afin que l''instructrice puisse observer votre posture de près et ajuster la résistance en temps réel, plutôt que de suivre un programme unique pour tous. Attendez-vous à un vrai défi complet : jambes, centre du corps et haut du corps sont souvent sollicités dans un même mouvement fluide.'
where slug = 'reformer-basics';

update public.course_types set
  description = 'A gentle, trimester-adapted class designed to keep you strong and comfortable throughout pregnancy, led by an instructor trained in prenatal movement. Every exercise is chosen with pregnancy-safe positioning in mind, avoiding anything that puts unnecessary pressure on the abdomen or strains an already-loosening pelvis. As your body changes week to week, the instructor adjusts the program with you rather than asking you to keep pace with a fixed routine, so the class still feels right whether you''re at twelve weeks or thirty-six. Beyond the physical side, many participants say the class is also where they get real, judgment-free answers to the small worries that come up during pregnancy.',
  description_de = 'Ein sanfter, auf das jeweilige Trimester abgestimmter Kurs, der dich während der Schwangerschaft stark und wohlfühlend hält, geleitet von einer in Prenatal-Bewegung geschulten Instruktorin. Jede Übung wird mit Blick auf schwangerschaftssichere Positionen ausgewählt und vermeidet alles, was unnötigen Druck auf den Bauch ausübt oder ein bereits gelockertes Becken belastet. Da sich dein Körper von Woche zu Woche verändert, passt die Instruktorin das Programm mit dir an, statt zu verlangen, mit einer festen Routine mitzuhalten — so passt der Kurs, ob du in der zwölften oder der sechsunddreissigsten Woche bist. Neben der körperlichen Seite sagen viele Teilnehmerinnen, dass sie hier auch echte, urteilsfreie Antworten auf die kleinen Sorgen der Schwangerschaft bekommen.',
  description_fr = 'Un cours doux, adapté à chaque trimestre, conçu pour vous garder forte et à l''aise tout au long de la grossesse, animé par une instructrice formée au mouvement prénatal. Chaque exercice est choisi en tenant compte des positions sûres pendant la grossesse, en évitant tout ce qui exercerait une pression inutile sur l''abdomen ou solliciterait un bassin déjà plus souple. Comme votre corps change de semaine en semaine, l''instructrice ajuste le programme avec vous plutôt que de vous demander de suivre une routine fixe, si bien que le cours reste adapté, que vous soyez à douze ou trente-six semaines. Au-delà de l''aspect physique, de nombreuses participantes disent que c''est aussi là qu''elles trouvent des réponses honnêtes et sans jugement aux petites inquiétudes de la grossesse.'
where slug = 'prenatal-pilates';

update public.course_types set
  description = 'One-on-one sessions tailored entirely to your goals, whether that''s rehab, technique, or simply a schedule that group classes don''t fit. Because there''s no group to accommodate, every minute of the hour is built specifically around your body — old injuries, current limitations, and whatever you''re actually trying to achieve, whether that''s returning to a sport, correcting a longstanding movement pattern, or building general strength at your own pace. The instructor tracks your progress session to session in detail, adjusting the program as you improve rather than repeating a fixed routine. It''s also the most flexible option for scheduling, making it a practical fit for anyone whose week doesn''t align with set class times.',
  description_de = 'Einzelstunden, die ganz auf deine Ziele zugeschnitten sind — ob Rehabilitation, Technik oder einfach ein Zeitplan, der nicht zu Gruppenkursen passt. Da keine Gruppe berücksichtigt werden muss, ist jede Minute der Stunde gezielt auf deinen Körper ausgerichtet — alte Verletzungen, aktuelle Einschränkungen und das, was du tatsächlich erreichen willst, ob Rückkehr zum Sport, Korrektur eines langjährigen Bewegungsmusters oder allgemeiner Kraftaufbau in deinem eigenen Tempo. Die Instruktorin verfolgt deinen Fortschritt von Stunde zu Stunde im Detail und passt das Programm an, statt eine feste Routine zu wiederholen. Es ist zudem die flexibelste Option für die Terminplanung — eine praktische Lösung für alle, deren Woche nicht zu festen Kurszeiten passt.',
  description_fr = 'Des séances individuelles entièrement adaptées à vos objectifs, qu''il s''agisse de rééducation, de technique, ou simplement d''un emploi du temps qui ne convient pas aux cours collectifs. Comme il n''y a aucun groupe à prendre en compte, chaque minute de la séance est construite spécifiquement autour de votre corps — anciennes blessures, limitations actuelles, et ce que vous cherchez réellement à accomplir, qu''il s''agisse de reprendre un sport, de corriger un schéma de mouvement ancien, ou simplement de renforcer votre corps à votre propre rythme. L''instructrice suit vos progrès en détail d''une séance à l''autre, ajustant le programme au fur et à mesure plutôt que de répéter une routine fixe. C''est aussi l''option la plus flexible pour la planification, un choix pratique pour quiconque a un emploi du temps qui ne correspond pas aux horaires fixes des cours collectifs.'
where slug = 'private-1-1';
